<?php
session_start();require_once __DIR__.'/../config/db.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$correo=trim($_POST['correo']??'');$password=$_POST['password']??'';$stmt=$pdo->prepare('SELECT id,nombre,correo,password FROM usuarios WHERE correo=? LIMIT 1');$stmt->execute([$correo]);$u=$stmt->fetch();if($u&&password_verify($password,$u['password'])){session_regenerate_id(true);$_SESSION['usuario']=['id'=>$u['id'],'nombre'=>$u['nombre'],'correo'=>$u['correo']];header('Location: panel.php');exit;}else{$error='Correo o contraseña incorrectos.';}}
